```csharp
using BenchmarkDotNet.Attributes;
using System;
using System.Reflection;

namespace MiscBenchmarks
{
    [MemoryDiagnoser]
    public class IsByRefLike
    {
        [Params(typeof(Span<byte>), typeof(string), typeof(int))]
        public Type type;

        private static readonly PropertyInfo s_isByRefLikePropertyInfo = typeof(Type).GetProperty("IsByRefLike");

        [Benchmark(Baseline = true)]
        public bool UseProperty()
        {
            return type.IsByRefLike;
        }

        [Benchmark]
        public bool LookupAttribute()
        {
            object[] attributes = type.GetCustomAttributes(inherit: false);

            for (int i = 0; i < attributes.Length; i++)
            {
                if (attributes[i].GetType().FullName == "System.Runtime.CompilerServices.IsByRefLikeAttribute")
                {
                    return true;
                }
            }

            return false;
        }

        [Benchmark]
        public bool UsePropertyWithReflection()
        {
            if (!type.IsValueType)
            {
                return false;
            }

            return (bool)(s_isByRefLikePropertyInfo.GetValue(type)!);
        }
    }
}
```
</details>

---

EDIT: the `IsByRefLike` property is just not available on .NET Framework & .NET Standard 2.0, so probing for it with reflection isn't helpful. Searching for the attribute seems to be the only viable fallback.

`IsByRefLikeAttribute` isn't available on .NET Standard 2.0, so we check for the attribute by name, not by type.

This reflection is cached so we'll only pay this cost during first-time serialization/warm-up.
